#Requires -Version 7.0
[CmdletBinding()]
param(
    [Parameter(Mandatory)][string]$Path,
    [string]$Filter = '*.ps*1'
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

Import-Module PSScriptAnalyzer -ErrorAction Stop
$files = if (Test-Path -LiteralPath $Path -PathType Container) {
    @(Get-ChildItem -LiteralPath $Path -File -Filter $Filter | Sort-Object Name | ForEach-Object FullName)
} else { @($Path) }
foreach ($file in $files) {
    $tokens = $null
    $errors = $null
    [void][System.Management.Automation.Language.Parser]::ParseFile($file, [ref]$tokens, [ref]$errors)
    $findings = @(Invoke-ScriptAnalyzer -Path $file -Severity Warning, Error)
    [pscustomobject]@{
        file          = $file
        sha256        = (Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash
        parseErrors   = @($errors).Count
        analyzerCount = $findings.Count
        findings      = @($findings | ForEach-Object { '{0}:{1} {2} {3}' -f $_.ScriptName, $_.Line, $_.RuleName, $_.Message })
    } | ConvertTo-Json -Depth 4 -Compress
}

