19	async function installClipboard(page: Page, denied: boolean, textOnly = false) {
20	  await page.addInitScript(({ denied, textOnly }) => {
21	    const state = window as unknown as { copiedInvitation: string | null };
22	    state.copiedInvitation = null;
23	    if (textOnly) Object.defineProperty(window, "ClipboardItem", { value: undefined, configurable: true });
24	    Object.defineProperty(navigator, "clipboard", {
25	      configurable: true,
26	      value: {
27	        async write(items: ClipboardItem[]) {
28	          if (denied) throw new DOMException("Denied", "NotAllowedError");
29	          state.copiedInvitation = await (await items[0].getType("text/plain")).text();
30	        },
31	        async writeText(text: string) {
32	          if (denied) throw new DOMException("Denied", "NotAllowedError");
33	          state.copiedInvitation = text;
34	        },
35	      },
36	    });
37	  }, { denied, textOnly });
38	}
39	
40	async function installRoom(page: Page, invitationFails = false, missingUrl = false) {
41	  const invitations: unknown[] = [];
42	  await page.route("**/api/session", (route) => route.fulfill({ json: { profile: player } }));
43	  await page.route("**/api/realtime", (route) => route.fulfill({ status: 503, json: { error: { code: "TEMPORARY_UNAVAILABLE" } } }));
44	  await page.route("**/api/rooms/**", (route) => {
45	    if (route.request().method() === "POST") {
46	      invitations.push(route.request().postDataJSON());
47	      if (invitationFails) return route.fulfill({ status: 503, json: { error: { code: "TEMPORARY_UNAVAILABLE" } } });
48	      if (missingUrl) return route.fulfill({ json: {} });
49	      return route.fulfill({ json: { url: invitation } });
50	    }
51	    return route.fulfill({ json: room });
52	  });
53	  if (process.env.WORDPAIRS_INVITE_MOCK_GATE === "1") {
54	    const mutant = process.env.WORDPAIRS_INVITE_MUTANT ?? "";
55	    await page.route("**/rooms/**", (route) => route.request().isNavigationRequest() ? route.fulfill({
56	      contentType: "text/html",
57	      body: `<!doctype html><html><body><button>Copy Invitation Link</button><div id="result"></div><p role="status"></p><div role="alert"></div><script>
58	        const mutant = ${JSON.stringify(mutant)};
59	        const button = document.querySelector('button');
60	        const status = document.querySelector('[role="status"]');
61	        const error = document.querySelector('[role="alert"]');
62	        button.onclick = async () => {
63	          button.disabled = true; status.textContent = ''; error.textContent = '';
64	          let provide, rejectData, copy;
65	          if (navigator.clipboard?.write && typeof ClipboardItem !== 'undefined') {
66	            const data = new Promise((resolve, reject) => { provide = resolve; rejectData = reject; });
67	            data.catch(() => {});
68	            try { copy = navigator.clipboard.write([new ClipboardItem({'text/plain': data})]).then(() => true, () => false); } catch { rejectData(); }
69	          }
70	          try {
71	            const payload = mutant === 'bad-request' ? {action:'invite'} : {action:'invite',expectedProfileId:'p1'};
72	            const response = await fetch('/api/rooms/${roomId}', {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
73	            if (!response.ok) {
74	              if (mutant === 'false-success') status.textContent = ${JSON.stringify(copiedMessage)};
75	              throw new Error('unavailable');
76	            }
77	            const result = await response.json();
78	            if ((typeof result.url !== 'string' || !result.url) && mutant !== 'missing-url-success') throw new Error('missing invitation');
79	            document.querySelector('#result').innerHTML = '<label>Shareable invitation link<input readonly></label>';
80	            document.querySelector('input').value = result.url;
81	            const copiedValue = mutant === 'bad-clipboard' ? 'https://wrong.example.test/' : result.url;
82	            if (provide) provide(new Blob([copiedValue], {type:'text/plain'}));
83	            let copied = copy ? await copy : false;
84	            if (!copy && navigator.clipboard?.writeText) { try { await navigator.clipboard.writeText(copiedValue); copied = true; } catch {} }
85	            status.textContent = copied || mutant === 'unavailable-success' ? ${JSON.stringify(copiedMessage)} : ${JSON.stringify(manualMessage)};
86	          } catch (failure) { error.textContent = failure.message === 'missing invitation' ? 'Room access is unavailable. Retry the same request.' : 'Your request was not confirmed. Retry the same request.'; }
87	          finally { if (rejectData) rejectData(new Error('no invitation')); button.disabled = false; }
88	        };
89	      </script></body></html>`,
90	    }) : route.fallback());
91	  }
92	  await page.goto(`/rooms/${roomId}`);
93	  return invitations;
94	}
95	
96	async function observeCopied(page: Page) {
97	  await page.getByRole("button", { name: "Copy Invitation Link", exact: true }).click();
98	  await expect(page.getByRole("status").filter({ hasText: copiedMessage })).toBeVisible();
99	  return {
100	    displayed: await page.getByLabel("Shareable invitation link").inputValue(),
101	    copied: await page.evaluate(() => (window as unknown as { copiedInvitation: string | null }).copiedInvitation),
102	  };
103	}
104	
105	async function observeManual(page: Page) {
106	  await page.getByRole("button", { name: "Copy Invitation Link", exact: true }).click();
107	  await expect(page.getByRole("status").filter({ hasText: manualMessage })).toBeVisible();
108	  return {
109	    displayed: await page.getByLabel("Shareable invitation link").inputValue(),
110	    copied: await page.evaluate(() => (window as unknown as { copiedInvitation: string | null }).copiedInvitation),
111	  };
112	}
113	
114	test("INVITE-COPY mock gate accepts correct copy and fallback and rejects corrupted outcomes", async ({ page }) => {
115	  const expected = { displayed: invitation, copied: invitation };
116	  for (const copied of [invitation, "https://wrong.example.test/"]) {
117	    await page.setContent(`<button>Copy Invitation Link</button><label>Shareable invitation link<input value="${invitation}"></label><p role="status"></p><script>
118	      document.querySelector("button").onclick = () => {
119	        window.copiedInvitation = ${JSON.stringify(copied)};
120	        document.querySelector('[role="status"]').textContent = ${JSON.stringify(copiedMessage)};
121	      };
122	    </script>`);
123	    const observed = await observeCopied(page);
124	    if (copied === invitation) expect(observed).toEqual(expected);
125	    else expect(() => expect(observed).toEqual(expected)).toThrow();
126	  }
127	  for (const displayed of [invitation, "https://wrong.example.test/"]) {
128	    await page.setContent(`<button>Copy Invitation Link</button><label>Shareable invitation link<input value="${displayed}"></label><p role="status"></p><script>
129	      document.querySelector("button").onclick = () => {
130	        window.copiedInvitation = null;
131	        document.querySelector('[role="status"]').textContent = ${JSON.stringify(manualMessage)};
132	      };
133	    </script>`);
134	    const observed = await observeManual(page);
135	    if (displayed === invitation) expect(observed).toEqual({ displayed: invitation, copied: null });
136	    else expect(() => expect(observed).toEqual({ displayed: invitation, copied: null })).toThrow();
137	  }
138	});
