140	test("INVITE-COPY-01 copies the generated invitation and confirms it", async ({ page }) => {
141	  await installClipboard(page, false);
142	  const invitations = await installRoom(page);
143	  expect(await observeCopied(page)).toEqual({ displayed: invitation, copied: invitation });
144	  expect(invitations).toHaveLength(1);
145	  expect(invitations[0]).toMatchObject({ action: "invite", expectedProfileId: "p1" });
146	});
