148	test("INVITE-COPY-01 uses writeText when ClipboardItem is unavailable", async ({ page }) => {
149	  await installClipboard(page, false, true);
150	  await installRoom(page);
151	  expect(await observeCopied(page)).toEqual({ displayed: invitation, copied: invitation });
152	});
