154	test("INVITE-COPY-02 preserves the link when clipboard access is denied", async ({ page }) => {
155	  await installClipboard(page, true);
156	  await installRoom(page);
157	  expect(await observeManual(page)).toEqual({ displayed: invitation, copied: null });
158	});
159	
160	test("INVITE-COPY-02 preserves the link when the clipboard API is unavailable", async ({ page }) => {
161	  await page.addInitScript(() => {
162	    (window as unknown as { copiedInvitation: string | null }).copiedInvitation = null;
163	    Object.defineProperty(navigator, "clipboard", { value: undefined, configurable: true });
164	  });
165	  await installRoom(page);
166	  expect(await observeManual(page)).toEqual({ displayed: invitation, copied: null });
167	});
168	
169	test("INVITE-COPY creation failure does not claim or perform a copy", async ({ page }) => {
170	  await installClipboard(page, false);
171	  await installRoom(page, true);
172	  const button = page.getByRole("button", { name: "Copy Invitation Link", exact: true });
173	  await button.click();
174	  await expect(page.getByRole("alert").filter({ hasText: "Your request was not confirmed" })).toBeVisible();
