Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$repo = '[HOME]/github/WordGame/.mcpServer/wordpairs'
Set-Location -LiteralPath $repo

function Get-RevisionSha256 {
    param([Parameter(Mandatory)][string]$Revision, [Parameter(Mandatory)][string]$RelativePath)
    $tmp = [System.IO.Path]::GetTempFileName()
    try {
        $psi = [System.Diagnostics.ProcessStartInfo]::new('git')
        $psi.ArgumentList.Add('show')
        $psi.ArgumentList.Add("$Revision`:$RelativePath")
