        try { $p.StandardOutput.BaseStream.CopyTo($fs) } finally { $fs.Dispose() }
        $p.WaitForExit()
        if ($p.ExitCode -ne 0) { return 'MISSING' }
        return (Get-FileHash -LiteralPath $tmp -Algorithm SHA256).Hash
    } finally { Remove-Item -LiteralPath $tmp -Force }
}

$revisions = [ordered]@{
    base  = '8e2f62417e0fe46cefd884e8a61024b12860a2cf'
