    foreach ($k in $revisions.Keys) { $row[$k] = (Get-RevisionSha256 -Revision $revisions[$k] -RelativePath $rel).Substring(0, 16) }
    $full = Join-Path $repo $rel
    $row['work'] = if (Test-Path -LiteralPath $full) { (Get-FileHash -LiteralPath $full -Algorithm SHA256).Hash.Substring(0, 16) } else { 'MISSING' }
    $row['mtime'] = if (Test-Path -LiteralPath $full) { (Get-Item -LiteralPath $full).LastWriteTime.ToString('s') } else { '' }
    [pscustomobject]$row | ConvertTo-Json -Compress
}
if ($ListPath) {
    foreach ($f in @(Get-ChildItem -LiteralPath $ListPath -File -Recurse | Sort-Object FullName)) {
        '{0} {1} {2}' -f (Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash.Substring(0, 16), $f.LastWriteTime.ToString('s'), $f.FullName.Substring($repo.Length + 1)
    }
}

