) => {
  if (!room || !profile || inFlight.current) return;
  inFlight.current = true;
  const epoch = commandEpoch.current;
  setBusy(true);
  setError("");
  if (action === "invite") setCopyMessage("");
  let provideCopy: ((url: string) => void) | undefined;
  let abortCopy: (() => void) | undefined;
  let copyResult: Promise<boolean> | undefined;
  if (
    action === "invite" &&
    navigator.clipboard?.write &&
    typeof ClipboardItem !== "undefined"
  ) {
    const content = new Promise<Blob>((resolve, reject) => {
      provideCopy = (url) => {
        resolve(new Blob([url], { type: "text/plain" }));
        provideCopy = undefined;
        abortCopy = undefined;
      };
      abortCopy = () => {
        reject(new Error("Invitation was not created"));
        provideCopy = undefined;
        abortCopy = undefined;
      };
    });
    // A denied clipboard request may stop observing the pending data promise.
    void content.catch(() => {});
    try {
      // Begin the clipboard operation during the click; its data arrives after
      // the server creates the inviter-bound link.
      copyResult = navigator.clipboard
        .write([new ClipboardItem({ "text/plain": content })])
        .then(
          () => true,
          () => false,
        );
    } catch {
      abortCopy?.();
    }
  }
  const input = pending.current ?? {
    action,
    expectedProfileId: profile.id,
    commandId: crypto.randomUUID(),
    expectedVersion: room.version,
    ...(mode ? { mode, inviterId: room.inviterId ?? selected } : {}),
    ...(action === "ready"
      ? { ready: !room.players.find((p) => p.id === profile.id)?.ready }
      : {}),
  };
  if (action !== "invite") pending.current = input;
  let explanation = "Room access is unavailable. Retry the same request.";
  try {
    const response = await fetch(
      ["ready", "leave"].includes(input.action as string)
        ? `/api/rooms/${encodeURIComponent(room.roomId)}/lobby`
        : endpoint,
      {
        method: "POST",
        signal: AbortSignal.timeout(10000),
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(input),
      },
    );
    if (epoch !== commandEpoch.current) {
      await response.text();
      return;
    }
    if ([401, 403, 404].includes(response.status)) {
      deny();
      await response.text();
      return;
    }
    const result = await response.json();
    if (epoch !== commandEpoch.current) return;
    if (response.ok || response.status < 500) {
      // A pre-command preview cannot decide membership or discovery recovery.
      // Retire it before clearing the canonical intent and read fresh state.
      sequence.current++;
      fetching.current = false;
      refreshAgain.current = false;
    }
    if (!response.ok) {
      if (response.status < 500) pending.current = null;
      if (
        fromDiscovery &&
        input.action === "join" &&
        input.mode === "player" &&
        response.status === 409
      ) {
        await refresh(true);
        return;
      }
      explanation =
        response.status === 409
          ? "The room or account changed. Refresh and try again."
          : "Your request was not confirmed. Retry the same request.";
      throw new Error("Unavailable");
    }
    pending.current = null;
    if (input.action === "leave") {
      window.location.assign("/play");
      return;
    }
    if (input.action === "invite") {
      if (typeof result.url !== "string" || !result.url) {
        throw new Error("Invalid invitation");
      }
      setLink(result.url);
      provideCopy?.(result.url);
      let copied = false;
      if (copyResult) {
        copied = await copyResult;
      } else {
        try {
          if (navigator.clipboard?.writeText) {
            await navigator.clipboard.writeText(result.url);
            copied = true;
          }
        } catch {
          // The visible link remains available for manual copying.
        }
      }
      if (epoch !== commandEpoch.current) return;
      setCopyMessage(
        copied
          ? "Invitation link copied."
          : "Could not copy automatically. Select the link to copy it.",
      );
    } else setActiveRef(result.roomId);
    await refresh();
  } catch {
    if (epoch === commandEpoch.current) setError(explanation);
  } finally {
    abortCopy?.();
    inFlight.current = false;
    if (epoch === commandEpoch.current) setBusy(false);
  }
};
const live = useRoomUpdates(
  profile?.id ?? null,
  room?.role ? room.roomId : null,
  refresh,

